(function(T,F){var D=window.SCD||{};for(var k in D)T=T.split("__"+k+"__").join(D[k]);var el=document.getElementById("sc");el.innerHTML=T+F;var ss=[].slice.call(el.querySelectorAll("script"));(function run(i){if(i>=ss.length)return;var o=ss[i],n=document.createElement("script");for(var a=0;a<o.attributes.length;a++)n.setAttribute(o.attributes[a].name,o.attributes[a].value);if(o.src){n.onload=n.onerror=function(){run(i+1)};o.parentNode.replaceChild(n,o)}else{n.text=o.text;o.parentNode.replaceChild(n,o);run(i+1)}})(0)})("<style>.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}#mf{color:var(--text-primary,#1d1b19)}#mf .steps{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px;font-size:12px}#mf .st{padding:4px 10px;border-radius:999px;background:var(--surface-1,#f1efeb);color:var(--text-muted,#8a847d)}#mf .st.d{background:#e3f3ea;color:#1f7a4d}#mf .st.n{background:#fbe8e0;color:#b4421b;font-weight:500}#mf h3{font-size:18px;font-weight:500;margin:0 0 4px}#mf .ds{font-size:14px;color:var(--text-secondary,#6b6660);margin:0 0 12px;line-height:1.6}#mf .mode{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px}#mf .mode button,#mf .seg,#mf .chip,#mf .go,#mf .all{font:inherit;color:inherit;cursor:pointer;-webkit-tap-highlight-color:transparent}#mf .mode button{text-align:left;padding:10px 12px;border-radius:10px;border:2px solid #d9d5cf;background:transparent}#mf .mode button b{display:block;font-size:14px;font-weight:500}#mf .mode button small{display:block;font-size:12px;color:var(--text-muted,#8a847d);margin-top:2px}#mf .mode button.on{border-color:#e8663a;background:rgba(232,102,58,.10)}#mf .bar{display:flex;align-items:center;gap:10px;margin:0 0 8px;font-size:13px;color:var(--text-secondary,#6b6660)}#mf .bar b{color:#b4421b;font-weight:500}#mf .all{margin-left:auto;font-size:13px;padding:6px 10px;border-radius:8px;border:1px solid #d9d5cf;background:transparent}#mf .list{display:flex;flex-direction:column;gap:8px}#mf .card{border:2px solid #d9d5cf;border-radius:12px;overflow:hidden}#mf .card.on{border-color:#e8663a}#mf .seg{display:flex;gap:10px;align-items:flex-start;width:100%;text-align:left;padding:10px 12px;border:0;background:transparent}#mf .card.on .seg{background:rgba(232,102,58,.10)}#mf .box{flex:none;width:22px;height:22px;border-radius:6px;border:2px solid #b5afa7;display:flex;align-items:center;justify-content:center;font-size:14px;color:transparent;background:#fff;margin-top:2px}#mf .card.on .box{background:#e8663a;border-color:#e8663a;color:#fff}#mf .thumb{flex:none;width:44px;height:78px;border-radius:6px;object-fit:cover;background:#ddd}#mf .seg b{display:block;font-size:14px;font-weight:500}#mf .seg small{display:block;font-size:12px;color:var(--text-muted,#8a847d);margin-top:2px;line-height:1.5}#mf .fix{padding:4px 12px 12px;border-top:1px dashed #e3dfd9}#mf .fix .q{font-size:12px;color:var(--text-secondary,#6b6660);margin:8px 0 6px}#mf .chips{display:flex;flex-wrap:wrap;gap:6px}#mf .chip{font-size:13px;padding:7px 10px;border-radius:999px;border:1.5px solid #d9d5cf;background:transparent}#mf .chip.on{border-color:#e8663a;background:#e8663a;color:#fff}#mf .chip.on::before{content:\"✓ \"}#mf input.nt{width:100%;margin-top:8px;font:inherit;font-size:13px;padding:8px 10px;border-radius:8px;border:1px solid #cfcac3;background:transparent;color:inherit;box-sizing:border-box}#mf .shared{margin-top:12px;border:2px solid #e8663a;border-radius:12px;padding:10px 12px}#mf .shared .q{font-size:13px;font-weight:500;margin:0 0 8px}#mf .err{font-size:13px;color:#c0392b;min-height:18px;margin:8px 0 0}#mf .go{margin-top:4px;padding:12px 18px;border-radius:10px;border:2px solid #e8663a;background:#e8663a;color:#fff;font-weight:500}#mf .links{margin-top:12px;font-size:13px}#mf .links a{color:var(--text-secondary,#6b6660)}#mf .tabs{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin:0 0 12px;padding:4px;border-radius:12px;background:var(--surface-1,#f1efeb)}#mf .tabs button{font:inherit;font-size:14px;padding:9px 8px;border:0;border-radius:9px;background:transparent;color:var(--text-secondary,#6b6660);cursor:pointer}#mf .tabs button.on{background:#e8663a;color:#fff;font-weight:500}#mf .fxrow{border:2px solid #d9d5cf;border-radius:12px;padding:10px 12px;margin-bottom:10px}#mf .fxrow h4{margin:0 0 2px;font-size:15px;font-weight:500}#mf .fxrow .cur{font-size:13px;color:var(--text-secondary,#6b6660);margin:0 0 8px}#mf .fxrow .cur b{color:#b4421b;font-weight:500}#mf .fxrow.chg{border-color:#e8663a}#mf .fxgrid{display:grid;grid-template-columns:1fr;gap:6px;max-height:340px;overflow:auto;padding-right:2px}@media (min-width:520px){#mf .fxgrid{grid-template-columns:1fr 1fr}}#mf .fxc{display:flex;gap:8px;align-items:center;text-align:left;width:100%;padding:6px;border-radius:10px;border:1.5px solid #d9d5cf;background:transparent;font:inherit;color:inherit;cursor:pointer}#mf .fxc img,#mf .fxc .ph{flex:none;width:40px;height:71px;border-radius:6px;object-fit:cover;background:#2a2622}#mf .fxc b{display:block;font-size:13px;font-weight:500}#mf .fxc small{display:block;font-size:11.5px;line-height:1.4;color:var(--text-muted,#8a847d)}#mf .fxc .fit{font-size:11px;font-weight:400;padding:1px 6px;border-radius:999px;background:#e3f3ea;color:#1f7a4d;margin-left:6px;vertical-align:1px}#mf .fxc.on{border-color:#e8663a;background:rgba(232,102,58,.12)}#mf .fxc.none{min-height:44px}#mf .see{font-family:inherit;font-size:12px;margin-left:auto;flex:none;padding:4px 6px;color:#b4421b;text-decoration:underline;background:none;border:0;cursor:pointer;white-space:nowrap}#mf .segpick{display:flex;flex-wrap:wrap;gap:6px;margin:6px 0 8px}#mf .segpick button{font:inherit;font-size:13px;padding:6px 10px;border-radius:999px;border:1.5px solid #d9d5cf;background:transparent;color:inherit;cursor:pointer}#mf .segpick button.on{border-color:#e8663a;background:#e8663a;color:#fff}#mf .midl{display:flex;flex-direction:column;gap:6px;margin:0 0 8px}#mf .midl div{display:flex;align-items:center;gap:8px;font-size:13px;padding:6px 10px;border-radius:8px;background:rgba(232,102,58,.10)}#mf .midl button{margin-left:auto;font:inherit;border:0;background:none;color:#c0392b;cursor:pointer;font-size:13px}#mf .addbtn{font:inherit;font-size:13px;padding:7px 12px;border-radius:8px;border:1.5px dashed #e8663a;background:transparent;color:#b4421b;cursor:pointer}@media (prefers-color-scheme:dark){#mf .fxrow,#mf .fxc,#mf .segpick button{border-color:#4a4642}#mf .fxc .fit{background:#173326;color:#6fd19c}}@media (prefers-color-scheme:dark){#mf .mode button,#mf .card,#mf .chip,#mf .all{border-color:#4a4642}#mf .box{background:transparent;border-color:#8a847d}#mf .st.d{background:#173326;color:#6fd19c}#mf .st.n{background:#3a2219;color:#f0794d}}</style>\n<h2 class=\"sr-only\">改动画：先选一起改还是一段一段改，勾要改的段落，每段（或全部）再点哪里不对。</h2>\n<div id=\"mf\">\n<div class=\"steps\"><span class=\"st d\">✓ 导入</span><span class=\"st d\">✓ 粗剪</span><span class=\"st d\">✓ 字幕</span><span class=\"st n\">→ 画面</span><span class=\"st\">音效</span><span class=\"st\">音乐</span><span class=\"st\">出片</span></div>\n<div class=\"tabs\" id=\"TABS\" style=\"__TABSHIDE__\"><button type=\"button\" data-tab=\"anim\" class=\"on\">改动画</button><button type=\"button\" data-tab=\"fx\">开头 / 结尾特效</button></div>\n<div id=\"P_anim\">\n<h3>要改哪几段动画？</h3>\n<p class=\"ds\">编号跟「__STILLS__」一样。先选怎么改，再勾段落、点哪里不对。</p>\n<div class=\"mode\"><button type=\"button\" data-m=\"each\" class=\"on\"><b>一段一段改</b><small>每段要改的不一样</small></button><button type=\"button\" data-m=\"same\"><b>选的这几段一起改</b><small>全部改一样的东西</small></button></div>\n<div class=\"bar\"><span>已选 <b id=\"cnt\">0</b> 段</span><button type=\"button\" class=\"all\" id=\"all\">全部都选</button></div>\n<div class=\"list\" id=\"L\"></div>\n<div class=\"shared\" id=\"SH\" style=\"display:none\"><p class=\"q\">这几段一起：哪里不对？（可以选好几个）</p><div class=\"chips\" data-s=\"shared\"></div><input class=\"nt\" data-n=\"shared\" type=\"text\" placeholder=\"补充想要的样子（可留空）\"></div>\n</div>\n<div id=\"P_fx\" style=\"display:none\">\n<h3>开头、结尾的特效</h3>\n<p class=\"ds\">换一个、拿掉，或在中间某一段多加一个。每个位置 46 个特效都可以选（绿色小字 = 比较适合放这里）；点「▶ 看示范」我发那个特效的示范片给你。</p>\n<div class=\"fxrow\" id=\"FX_open\"></div>\n<div class=\"fxrow\" id=\"FX_end\"></div>\n<div class=\"fxrow\" id=\"FX_mid\"></div>\n</div>\n<p class=\"err\" id=\"err\" role=\"alert\"></p>\n<button type=\"button\" class=\"go\" id=\"go\">下一步 ↗</button>\n<div class=\"links\"><a href=\"#\" data-p=\"我是剪辑新手，看不懂现在这一步。请用最简单的话告诉我现在要做什么，再给我按钮选。\">我看不懂</a></div>\n</div>\n<script>(function(){\nvar SEGS=__SEGS__, ISSUES=__ISSUES__, FXCAT=__FXCAT__, FXCUR=__FXCUR__, TAB0=__TAB0__;\nvar tab=FXCAT.length?(TAB0||'anim'):'anim', fx={open:null,end:null,mid:[]}, open_={open:false,end:false,mid:false}, midSeg=null, midKey=null;\nvar root=document.getElementById('mf'),L=document.getElementById('L'),SH=document.getElementById('SH');\nvar mode='each',sel={},pick={shared:{}},note={shared:''};\nfunction esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/\"/g,'&quot;')}\nfunction chips(key){return ISSUES.map(function(o){return '<button type=\"button\" class=\"chip'+(pick[key]&&pick[key][o.v]?' on':'')+'\" data-k=\"'+key+'\" data-v=\"'+esc(o.v)+'\" title=\"'+esc(o.sub||'')+'\">'+esc(o.label)+'</button>'}).join('')}\nvar WN={open:'适合开头',end:'适合结尾',mid:'适合中间'};\nfunction fxcard(m,on,where){var fit=(m.slots||[]).indexOf(where)>=0;return '<button type=\"button\" class=\"fxc'+(on?' on':'')+'\" data-fx=\"'+where+'\" data-k=\"'+esc(m.key)+'\">'+(m.thumb?'<img src=\"'+m.thumb+'\" alt=\"\">':'<span class=\"ph\"></span>')+'<span><b>'+esc(m.no+' '+m.name)+(fit?'<span class=\"fit\">'+WN[where]+'</span>':'')+'</b><small>'+esc(m.desc||'')+(m.hint?'（'+esc(m.hint)+'）':'')+'</small></span><span class=\"see\" role=\"button\" data-see=\"'+esc(m.name)+'\">▶ 看示范</span></button>'}\nfunction nameOf(k){for(var i=0;i<FXCAT.length;i++)if(FXCAT[i].key===k)return FXCAT[i].name;return k}\nfunction fxrow(where,label){\nvar el=document.getElementById('FX_'+where),cur=FXCUR[where],sel=fx[where];\nvar now=sel===null?(cur?'现在：<b>'+esc(cur.name)+'</b>':'现在：没有特效'):(sel==='none'?'改成：<b>不要特效</b>':'改成：<b>'+esc(nameOf(sel))+'</b>');\nvar h='<h4>'+label+'</h4><p class=\"cur\">'+now+'</p>';\nif(open_[where]){var list=FXCAT;\nh+='<div class=\"fxgrid\"><button type=\"button\" class=\"fxc none'+(sel==='none'?' on':'')+'\" data-fx=\"'+where+'\" data-k=\"none\"><span><b>不要'+label+'</b><small>这里不放特效</small></span></button>'+list.map(function(m){return fxcard(m,sel===m.key,where)}).join('')+'</div>'}\nelse h+='<button type=\"button\" class=\"addbtn\" data-open=\"'+where+'\">'+(sel===null?'换一个':'再换')+'</button>'+(sel!==null?' <button type=\"button\" class=\"addbtn\" data-undo=\"'+where+'\">还原</button>':'');\nel.innerHTML=h; el.classList.toggle('chg',sel!==null)}\nfunction midrow(){\nvar el=document.getElementById('FX_mid'),h='<h4>中间加特效</h4><p class=\"cur\">选哪一段，再选特效（可以加好几个）</p>';\nif(fx.mid.length)h+='<div class=\"midl\">'+fx.mid.map(function(m,i){return '<div>第 '+esc(m.n)+' 段 → '+esc(nameOf(m.key))+'<button type=\"button\" data-rm=\"'+i+'\">✕ 拿掉</button></div>'}).join('')+'</div>';\nif(open_.mid){h+='<p class=\"cur\">① 哪一段：</p><div class=\"segpick\">'+SEGS.map(function(s){return '<button type=\"button\" data-ms=\"'+esc(s.n)+'\" class=\"'+(String(midSeg)===String(s.n)?'on':'')+'\">'+esc(s.n)+' · '+esc(s.t)+'</button>'}).join('')+'</div><p class=\"cur\">② 哪个特效：</p><div class=\"fxgrid\">'+FXCAT.map(function(m){return fxcard(m,midKey===m.key,'mid')}).join('')+'</div>'}\nelse h+='<button type=\"button\" class=\"addbtn\" data-open=\"mid\">＋ 加一段特效</button>';\nel.innerHTML=h; el.classList.toggle('chg',fx.mid.length>0)}\nfunction draw(){\ndocument.getElementById('P_anim').style.display=tab==='anim'?'':'none';document.getElementById('P_fx').style.display=tab==='fx'?'':'none';\nroot.querySelectorAll('#TABS button').forEach(function(b){b.classList.toggle('on',b.dataset.tab===tab)});\nfxrow('open','开头特效');fxrow('end','结尾特效');midrow();\nL.innerHTML=SEGS.map(function(s){var on=!!sel[s.n],k=String(s.n);pick[k]=pick[k]||{};\nreturn '<div class=\"card'+(on?' on':'')+'\"><button type=\"button\" class=\"seg\" data-n=\"'+k+'\"><span class=\"box\" aria-hidden=\"true\">✓</span>'+(s.img?'<img class=\"thumb\" src=\"'+s.img+'\" alt=\"\">':'')+'<span><b>'+esc(s.n)+' · '+esc(s.t)+' '+esc(s.what)+'</b><small>'+esc(s.say||'')+'</small></span></button>'+\n(on&&mode==='each'?'<div class=\"fix\"><p class=\"q\">第 '+esc(s.n)+' 段哪里不对？（可以选好几个）</p><div class=\"chips\">'+chips(k)+'</div><input class=\"nt\" data-n=\"'+k+'\" type=\"text\" placeholder=\"补充第 '+esc(s.n)+' 段想要的样子（可留空）\" value=\"'+esc(note[k]||'')+'\"></div>':'')+'</div>'}).join('');\nSH.style.display=mode==='same'?'':'none';SH.querySelector('.chips').innerHTML=chips('shared');\ndocument.getElementById('cnt').textContent=Object.keys(sel).length;\nroot.querySelectorAll('.mode button').forEach(function(b){b.classList.toggle('on',b.dataset.m===mode)});\ndocument.getElementById('all').textContent=Object.keys(sel).length===SEGS.length?'全部取消':'全部都选';\n}\nroot.addEventListener('click',function(e){\nvar sv=e.target.closest('[data-see]');if(sv&&root.contains(sv)){e.preventDefault();e.stopPropagation();scSend('给我看「'+sv.dataset.see+'」这个特效的示范片');return}\nvar b=e.target.closest('button,a');if(!b||!root.contains(b))return;\nif(b.dataset.p){e.preventDefault();scSend(b.dataset.p);return}\nif(b.dataset.tab){tab=b.dataset.tab}\nelse if(b.dataset.open){open_[b.dataset.open]=true}\nelse if(b.dataset.undo){fx[b.dataset.undo]=null}\nelse if(b.dataset.rm){fx.mid.splice(+b.dataset.rm,1)}\nelse if(b.dataset.ms){midSeg=b.dataset.ms;if(midKey){fx.mid.push({n:midSeg,key:midKey});midSeg=midKey=null;open_.mid=false}}\nelse if(b.dataset.fx){var w=b.dataset.fx,k=b.dataset.k;\nif(w==='mid'){midKey=k;if(midSeg){fx.mid.push({n:midSeg,key:midKey});midSeg=midKey=null;open_.mid=false}}\nelse{fx[w]=(FXCUR[w]&&FXCUR[w].key===k)?null:k;open_[w]=false}}\nelse if(b.dataset.m){mode=b.dataset.m}\nelse if(b.id==='all'){if(Object.keys(sel).length===SEGS.length)sel={};else SEGS.forEach(function(s){sel[s.n]=1})}\nelse if(b.classList.contains('seg')){var n=b.dataset.n;if(sel[n])delete sel[n];else sel[n]=1}\nelse if(b.classList.contains('chip')){var k=b.dataset.k,v=b.dataset.v;pick[k]=pick[k]||{};if(pick[k][v])delete pick[k][v];else pick[k][v]=1}\nelse if(b.id==='go'){go();return}\nelse return;\ndocument.getElementById('err').textContent='';draw()});\nroot.addEventListener('input',function(e){var i=e.target.closest('input.nt');if(i)note[i.dataset.n]=i.value});\nfunction list(k){return ISSUES.filter(function(o){return pick[k]&&pick[k][o.v]}).map(function(o){return o.v})}\nfunction fxmsg(){var p=[];\n['open','end'].forEach(function(w){var v=fx[w],lab=w==='open'?'开头':'结尾';if(v===null)return;p.push(v==='none'?lab+'不要特效':lab+'换成「'+nameOf(v)+'」（'+v+'）')});\nfx.mid.forEach(function(m){p.push('第 '+m.n+' 段加「'+nameOf(m.key)+'」（'+m.key+'）')});\nreturn p.length?'特效要改：'+p.join('；')+'。':''}\nfunction go(){var ns=SEGS.filter(function(s){return sel[s.n]}).map(function(s){return String(s.n)}),err=document.getElementById('err'),fm=fxmsg();\nif(!ns.length&&!fm){err.textContent=tab==='fx'?'还没改特效：点「换一个」或「＋ 加一段特效」':'还没选段落：点一下段落，出现 ✓ 和橘色框就是选到了';return}\nif(!ns.length){scSend(fm);return}\nvar msg;\nif(mode==='same'){var p=list('shared'),t=(note.shared||'').trim();\nif(!p.length&&!t){err.textContent='还没选哪里不对：点下面的选项，或写一下想要的样子';return}\nmsg='动画要改（第 '+ns.join('、')+' 段一起改）：'+p.join('、')+(t?'。补充：'+t:'')+'。'}\nelse{var miss=ns.filter(function(n){return !list(n).length&&!(note[n]||'').trim()});\nif(miss.length){err.textContent='第 '+miss.join('、')+' 段还没选哪里不对（每段点一个以上，或写补充）';return}\nmsg='动画要改（一段一段改）：\\n'+ns.map(function(n){var t=(note[n]||'').trim();return '第 '+n+' 段：'+list(n).join('、')+(t?(list(n).length?'。':'')+'补充：'+t:'')}).join('\\n')}\nscSend(msg+(fm?'\\n'+fm:''))}\ndraw()})();</script>\n","<p class=\"sc-foot\" style=\"margin:8px 2px 0;font-size:12px;color:var(--text-muted,#8a847d)\">按了没反应？等我停下来再按，或直接在对话框打按钮上的字。</p><script>(function(){if(window.scSend&&window.scSend.ok)return;function B(t,f){var e=document.getElementById('sc-fb');if(!e){e=document.createElement('details');e.id='sc-fb';e.style.cssText='margin:10px 2px 0;padding:8px 12px;border-radius:10px;font-size:12.5px;line-height:1.6;border:1px solid #e8663a66;background:#e8663a12;color:inherit';var o=document.querySelector('.sc-foot');o?o.parentNode.insertBefore(e,o):document.body.appendChild(e)}var s=t.length>40?t.slice(0,40)+'…':t;e.innerHTML='<summary style=\"cursor:pointer\">'+(f?'<b>这个按钮没送出去</b> · 点这里看怎么办':'已送出：「'+s.replace(/</g,'&lt;')+'」· 对话框没出现？点这里')+'</summary><div>Claude 还在跑时按钮会没反应。等它停下来再按，或复制这句贴到对话框送出：</div><textarea readonly rows=\"2\" style=\"display:block;width:100%;box-sizing:border-box;margin-top:6px;padding:6px 8px;border-radius:8px;border:1px solid #d9d5cf;font:inherit;background:transparent;color:inherit\"></textarea><button type=\"button\" style=\"margin-top:6px;padding:4px 12px;border-radius:8px;border:1px solid #d9d5cf;background:transparent;color:inherit;font:inherit;cursor:pointer\">复制这句</button>';var a=e.querySelector('textarea'),b=e.querySelector('button');a.value=t;b.onclick=function(v){v.preventDefault();a.focus();a.select();var k=0;try{k=document.execCommand('copy')}catch(x){}try{navigator.clipboard&&(navigator.clipboard.writeText(t),k=1)}catch(x){}b.textContent=k?'已复制，贴到对话框送出':'已选取，按 ⌘C / Ctrl+C 复制'};if(f)e.open=true}window.scSend=function(t){t=String(t==null?'':t);var f=0;try{if(typeof sendPrompt!='function')f=1;else{var r=sendPrompt(t);r&&r.then&&r.then(null,function(){B(t,1)})}}catch(x){f=1}B(t,f)};window.scSend.ok=1})();</script>");